# Read-only state of the existing 606b / 16b82 transaction. Never repairs or reads DPAPI.
function Get-RcRecoveryAclDifference([string]$CurrentSddl,[string]$BackupSddl){
    $a=New-Object Security.AccessControl.RawSecurityDescriptor($CurrentSddl);$b=New-Object Security.AccessControl.RawSecurityDescriptor($BackupSddl)
    $ap=($a.ControlFlags-band[Security.AccessControl.ControlFlags]::DiscretionaryAclProtected)-ne0;$bp=($b.ControlFlags-band[Security.AccessControl.ControlFlags]::DiscretionaryAclProtected)-ne0
    $ac=if($null-eq$a.DiscretionaryAcl){-1}else{$a.DiscretionaryAcl.Count};$bc=if($null-eq$b.DiscretionaryAcl){-1}else{$b.DiscretionaryAcl.Count}
    return [ordered]@{ownerMatches=($a.Owner.Value-ceq$b.Owner.Value);groupMatches=($a.Group.Value-ceq$b.Group.Value);daclProtectedMatches=($ap-eq$bp);aceCountMatches=($ac-eq$bc);currentDaclProtected=$ap;backupDaclProtected=$bp;currentAceCount=$ac;backupAceCount=$bc}
}
function Read-RcRecoveryIndex([byte[]]$Bytes,[hashtable]$Expected){
    # WinPS5 emits a JSON array as one pipeline object; @() would nest it.
    $entries=ConvertFrom-Json -InputObject ([Text.Encoding]::UTF8.GetString($Bytes)) -ErrorAction Stop
    if($entries-isnot[Array]-or$entries.Count-ne8-or$Expected.Count-ne8){throw 'recovery_index_invalid'}
    $keys=@{};$names=@{}
    foreach($e in $entries){
        if($null-eq$e-or$e.key-isnot[string]-or$e.path-isnot[string]-or$e.backup-isnot[string]-or$e.sha256-isnot[string]-or$e.sddl-isnot[string]-or$e.key-cnotin$Expected.Keys-or$keys.ContainsKey($e.key)-or$e.path-cne$Expected[$e.key]-or$e.backup-cnotmatch'^file-[0-7]\.bin$'-or$names.ContainsKey($e.backup)-or$e.sha256-cnotmatch'^[a-f0-9]{64}$'-or$e.sddl.Length-gt65536){throw 'recovery_index_invalid'}
        $keys[$e.key]=$true;$names[$e.backup]=$true
        try{$null=New-Object Security.AccessControl.RawSecurityDescriptor($e.sddl)}catch{throw 'recovery_index_invalid'}
    }
    return ,$entries
}
function Select-RcRecoveryJournal([string[]]$Lines){
