    foreach($line in @($Lines|Select-Object -Last 64)){try{if($line.Length-gt8192){throw 'invalid'};$r=$line|ConvertFrom-Json;$stamp=[DateTimeOffset]::MinValue;if($r.schemaVersion-ne1-or$r.installationId-cne'606b8c29-41de-4dc0-b63d-ade836000d9e'-or$r.stage-cnotin$allowed-or$r.committed-isnot[bool]-or$r.rollbackStatus-cnotin@('not_needed','rollback_partial','rollback_restored_service_stopped','rollback_restored_service_started')-or$r.utc-isnot[string]-or-not[DateTimeOffset]::TryParseExact($r.utc,'o',[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::None,[ref]$stamp)){throw 'invalid'};$records+=@([ordered]@{utc=$stamp.ToUniversalTime().ToString('o');stage=[string]$r.stage;committed=$r.committed;rollbackStatus=[string]$r.rollbackStatus})}catch{$invalid++}}
    return [ordered]@{status='read';records=$records;invalidRows=$invalid;returnedLimit=64}
}
function Select-RcRecoveryAddresses($Values){$safe=@();foreach($v in @($Values|Select-Object -First 8)){$text=[string]$v;if(($text.Length-le64-and$text-cmatch'^[0-9.]+(?:/[0-9.]+|-[0-9.]+)?$')-or$text-cin@('Any','LocalSubnet','LocalSubnet4','LocalSubnet6','Internet','Intranet','DefaultGateway','DHCP','DNS','WINS')){$safe+=@($text)}else{$safe+=@('unlisted')}};return ,$safe}
function Test-RcRecoveryPrincipalLocalMatch([string]$Observed,[string]$ExpectedSid,[string]$LocalMachine,[string]$LocalName){
    try{$expected=(New-Object Security.Principal.SecurityIdentifier($ExpectedSid)).Value;if($Observed-cmatch'^S-1-'){return (New-Object Security.Principal.SecurityIdentifier($Observed)).Value-ceq$expected}}catch{return $null}
    if([string]::IsNullOrEmpty($LocalMachine)-or[string]::IsNullOrEmpty($LocalName)-or$LocalMachine.Contains('\')-or$LocalName.Contains('\')-or$LocalName.Contains('@')){return $null}
    $prefix=if($Observed.StartsWith('.\',[StringComparison]::Ordinal)){'.\'}elseif($Observed.StartsWith(($LocalMachine+'\'),[StringComparison]::OrdinalIgnoreCase)){$LocalMachine+'\'}else{return $null}
    $name=$Observed.Substring($prefix.Length);if($name.Contains('\')-or$name.Contains('@')-or$name.Length-eq0){return $null};return [string]::Equals($name,$LocalName,[StringComparison]::OrdinalIgnoreCase)
}
function Read-RcRecoveryPrivateBytes([string]$Path){
